{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is missing a Public Access block, which could expose it to unauthorized access."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket does not have block public ACLS enabled, making it vulnerable to public access through ACLs."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The S3 bucket lacks access logging, which is crucial for monitoring and auditing access to the bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"changeme_aws_s3_bucket_backend_simple\" {\n  force_destroy = true\n  bucket        = \"changeme-${random_id.changeme_backends_s3_bucket_name.hex}\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_logging\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n\n  target_bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n  target_prefix = \"logs/\"\n}",
  "fix_summary": "Added aws_s3_bucket_public_access_block to block public access and aws_s3_bucket_logging to enable access logging for the S3 bucket."
}
